// src/utils/odiaUtils.ts
function toOdiaNum(value) {
  const str = String(value);
  let out = "";
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    if (ch >= "0" && ch <= "9") {
      out += String.fromCharCode(2918 + (ch.charCodeAt(0) - 48));
    } else {
      out += ch;
    }
  }
  return out;
}
function fromOdiaNum(value) {
  let out = "";
  for (let i = 0; i < value.length; i++) {
    const code = value.charCodeAt(i);
    if (code >= 2918 && code <= 2927) {
      out += String.fromCharCode(48 + (code - 2918));
    } else {
      out += value[i];
    }
  }
  return out;
}
