function convertToEnglishWords(n) {
  if (!Number.isFinite(n) || n < 0) return "";
  const intVal = Math.floor(n);
  if (intVal === 0) return "Zero";
  function convertLessThanThousand(num) {
    if (num === 0) return "";
    if (num < 20) return ENG_UNITS[num];
    if (num < 100) {
      const u = num % 10;
      return `${ENG_TENS[Math.floor(num / 10)]}${u !== 0 ? " " + ENG_UNITS[u] : ""}`;
    }
    const rem2 = num % 100;
    return `${ENG_UNITS[Math.floor(num / 100)]} Hundred${rem2 !== 0 ? " " + convertLessThanThousand(rem2) : ""}`;
  }
  let rem = intVal;
  const parts = [];
  if (rem >= 1e7) {
    const crores = Math.floor(rem / 1e7);
    parts.push(`${convertToEnglishWords(crores)} Crore`);
    rem %= 1e7;
  }
  if (rem >= 1e5) {
    const lakhs = Math.floor(rem / 1e5);
    parts.push(`${convertLessThanThousand(lakhs)} Lakh`);
    rem %= 1e5;
  }
  if (rem >= 1e3) {
    const thousands = Math.floor(rem / 1e3);
    parts.push(`${convertLessThanThousand(thousands)} Thousand`);
    rem %= 1e3;
  }
  if (rem > 0) {
    parts.push(convertLessThanThousand(rem));
  }
  return parts.join(" ").trim();
}
